import React, { useEffect, useState } from "react";
import { securedAxiosInstance } from "../../axiosConfig";
import Loader from "../../components/Loader";
import { Announcement } from "../../types/notice";
import { Company } from "../../types/company";
import { useNavigate, useParams } from "react-router-dom";
import { Card } from "@themesberg/react-bootstrap";
import { formatDate } from "../../utils/dateformatter";
import "react-quill/dist/quill.snow.css";
import HtmlText from "../../components/HtmlToText/HtmlText";

const useNoticeData = (eventid: string | undefined) => {
  const [announcement, setAnnouncement] = useState<Announcement | null>(null);
  const [company, setCompany] = useState<Company | null>(null);
  const [relatedNotices, setRelatedNotices] = useState<Announcement[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(false);

  useEffect(() => {
    const fetchData = async () => {
      if (!eventid) return;
      
      try {
        setLoading(true);
        setError(false);
        
        // Fetch main announcement
        const announcementRes = await securedAxiosInstance.get<Announcement>(`/announcements/${eventid}`);
        const announcementData = announcementRes.data;
        setAnnouncement(announcementData);

        // Fetch company info if exists
        if (announcementData.company_id) {
          try {
            const companyRes = await securedAxiosInstance.get<Company>(`/companies/${announcementData.company_id}`);
            setCompany(companyRes.data);
          } catch (e) {
            console.log("Company fetch failed:", e);
          }
        }

        // Fetch related notices
        try {
          const relatedRes = await securedAxiosInstance.get<Announcement[]>(
            `/announcements?event_id=${announcementData.event_id || announcementData.id}&_sort=published_at:desc&_limit=10`
          );
          setRelatedNotices(relatedRes.data.filter(n => n.id !== announcementData.id));
        } catch (e) {
          console.log("Related notices fetch failed:", e);
        }

      } catch (err) {
        setError(true);
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, [eventid]);

  return { announcement, company, relatedNotices, loading, error };
};

const Attachments = ({ attachments }: { attachments: any[] | undefined }) => {
  if (!attachments?.length) return null;

  return (
    <div className="mt-4 pt-3 border-top">
      <h6 className="mb-3">
        <i className="fas fa-paperclip me-2"></i>
        Attachments ({attachments.length})
      </h6>
      
      {attachments.map((attachment, index) => (
        <div
          key={index}
          className="d-flex align-items-center justify-content-between p-3 mb-2 bg-light border rounded"
          style={{ cursor: "pointer" }}
          onClick={() => window.open(attachment.url)}
        >
          <div className="d-flex align-items-center gap-3">
            <div className="bg-primary text-white rounded d-flex align-items-center justify-content-center" 
                 style={{ width: "32px", height: "32px", fontSize: "10px", fontWeight: "600" }}>
              PDF
            </div>
            <div>
              <div className="fw-medium" style={{ fontSize: "14px" }}>{attachment.name}</div>
              <small className="text-muted">
                {(attachment.size / (1024 * 1024)).toFixed(2)} MB • {attachment.ext?.toUpperCase() || 'PDF'}
              </small>
            </div>
          </div>
          <button className="btn btn-sm btn-outline-primary">
            <i className="fas fa-download me-1"></i>Download
          </button>
        </div>
      ))}
    </div>
  );
};

const CompanyInfo = ({ company }: { company: Company | null }) => {
  if (!company) return null;

  return (
    <Card className="mt-3 border" style={{ borderColor: "#e5e7eb" }}>
      <Card.Body className="p-4">
        <h5 className="mb-3">
          <i className="fas fa-building text-primary me-2"></i>
          Company Information
        </h5>
        
        <h6 className="fw-bold mb-2">{company.name || company.Name}</h6>
        
        {company.info && (
          <div className="text-muted mb-3" style={{ fontSize: "14px" }}>
            <HtmlText content={company.info} small={true} />
          </div>
        )}

        <div className="d-flex flex-wrap gap-2 mb-3">
          {company.company_category && (
            <span className="badge bg-light text-dark" style={{ fontSize: "13px", padding: "6px 12px" }}>
              <i className="fas fa-tag me-1"></i>
              {company.company_category}
            </span>
          )}
        </div>

        {company.company_turnover && (
          <div className="text-muted" style={{ fontSize: "13px" }}>
            <i className="fas fa-chart-line me-1"></i>
            Turnover: {company.company_turnover}
          </div>
        )}

        {company.events && company.events.length > 0 && (
          <div className="mt-2 text-muted" style={{ fontSize: "13px" }}>
            <i className="fas fa-calendar me-1"></i>
            {company.events.length} event{company.events.length > 1 ? 's' : ''}
          </div>
        )}
      </Card.Body>
    </Card>
  );
};

const RelatedNotices = ({ notices }: { notices: Announcement[] }) => {
  const navigate = useNavigate();
  const truncateContent = (content: string, maxLength: number = 120) => {
    if (!content) return "";
    const textContent = content.replace(/<[^>]*>/g, ''); // Remove HTML tags
    if (textContent.length <= maxLength) return textContent;
    return textContent.substring(0, maxLength).trim() + "...";
  };

  return (
    <Card className="border" style={{ height: "100vh", borderColor: "#e5e7eb" }}>
      <Card.Body className="p-3 d-flex flex-column">
        <h6 className="mb-3">
          <i className="fas fa-list text-primary me-2"></i>
          {notices.length > 0 ? `Related Notices (${notices.length})` : 'Related Notices'}
        </h6>

        <div className="flex-grow-1" style={{ overflowY: "auto" }}>
          {notices.length === 0 ? (
            <p className="text-muted text-center py-3 mb-0" style={{ fontSize: "14px" }}>
              <i className="fas fa-info-circle me-2"></i>
              No related notices found
            </p>
          ) : (
            notices.map((notice) => {
              const contentText = notice.content ? 
                (typeof notice.content === 'string' ? notice.content : JSON.stringify(notice.content)) : 
                "";
              const truncatedContent = truncateContent(contentText, 100);
              const isContentTruncated = contentText.replace(/<[^>]*>/g, '').length > 100;

              return (
                <div
                  key={notice.id}
                  className="p-2 border rounded mb-2"
                  style={{ 
                    cursor: "pointer", 
                    borderColor: "#e5e7eb",
                    transition: "all 0.2s ease"
                  }}
                  onMouseEnter={(e) => {
                    e.currentTarget.style.backgroundColor = "#f8f9fa";
                  }}
                  onMouseLeave={(e) => {
                    e.currentTarget.style.backgroundColor = "transparent";
                  }}
                  onClick={() => navigate(notice.redirect_url ?? `/notices/${notice.id}`)}
                >
                  <div className="d-flex justify-content-between align-items-start mb-2">
                    <small className="text-muted d-flex align-items-center" style={{ fontSize: "11px" }}>
                      <i className="fas fa-calendar-alt me-1"></i>
                      {notice.published_at ? formatDate(notice.published_at) : 'No date'}
                    </small>
                    {notice.tag && (
                      <span className="badge bg-secondary" style={{ fontSize: "11px", padding: "4px 8px" }}>
                        {notice.tag}
                      </span>
                    )}
                  </div>
                  
                  <div className="fw-bold mb-2" style={{ fontSize: "15px", lineHeight: "1.3" }}>
                    {notice.title}
                  </div>
                  
                  <div style={{ fontSize: "12px", color: "#6b7280", lineHeight: "1.4" }}>
                    {truncatedContent}
                    {isContentTruncated && (
                      <span className="text-primary fw-medium" style={{ marginLeft: "4px" }}>
                        Click to view more
                      </span>
                    )}
                  </div>
                </div>
              );
            })
          )}
        </div>
      </Card.Body>
    </Card>
  );
};

const NoticeContent = ({ announcement }: { announcement: Announcement }) => (
  <Card className="border" style={{ minHeight: "60vh", borderColor: "#e5e7eb" }}>
    <Card.Body className="p-4 d-flex flex-column">
      <div className="d-flex justify-content-between align-items-start mb-4">
        <div className="d-flex flex-wrap gap-2">
          <span className="badge bg-light text-dark" style={{ fontSize: "13px", padding: "6px 12px" }}>
            {announcement.type === 'CompanyEvent' ? 'Company Event' : 'General Notice'}
          </span>
          {announcement.tag && (
            <span className="badge bg-primary" style={{ fontSize: "13px", padding: "6px 12px" }}>
              {announcement.tag}
            </span>
          )}
          {announcement.batches?.length && (
            <span className="badge bg-secondary" style={{ fontSize: "13px", padding: "6px 12px" }}>
              {announcement.batches.join(", ")}
            </span>
          )}
        </div>
        
        <button 
          className="btn btn-outline-secondary btn-sm"
          onClick={() => window.print()}
          title="Print Notice"
        >
          <i className="fas fa-print"></i>
        </button>
      </div>

      {/* Title */}
      <h1 className="fw-bold mb-4" style={{ fontSize: "28px", lineHeight: "1.2" }}>
        {announcement.title}
      </h1>

      {/* Meta Info */}
      <div className="d-flex flex-wrap gap-4 mb-4 pb-3 border-bottom" style={{ fontSize: "14px" }}>
        {announcement.published_at && (
          <span className="text-muted">
            <i className="fas fa-calendar me-2"></i>
            {formatDate(announcement.published_at)}
          </span>
        )}
        {announcement.company && (
          <span className="text-muted">
            <i className="fas fa-building me-2"></i>
            {announcement.company}
          </span>
        )}
        {announcement.degrees?.length && (
          <span className="text-muted">
            <i className="fas fa-graduation-cap me-2"></i>
            {announcement.degrees.length >= 7 ? "All Degrees" : announcement.degrees.join(", ")}
          </span>
        )}
      </div>

      {/* Content - flexible grow */}
      <div className="flex-grow-1 mb-4" style={{ fontSize: "16px", lineHeight: "1.7" }}>
        <HtmlText content={announcement.content ?? ""} small={false} />
      </div>

      <Attachments attachments={announcement.attachment} />
    </Card.Body>
  </Card>
);

export default function CompanyNoticeDetails() {
  const { eventid } = useParams();
  const { announcement, company, relatedNotices, loading, error } = useNoticeData(eventid);

  if (loading) return <Loader />;
  if (error) return (
    <div className="alert alert-danger">Error loading announcement</div>
  );
  if (!announcement) return (
    <div className="alert alert-warning">No announcement found</div>
  );

  return (
    <div className="p-3">
      <div className="row g-3" style={{ minHeight: "100vh" }}>
        {/* Main Content Column */}
        <div className="col-lg-8 d-flex flex-column">
          <NoticeContent announcement={announcement} />
          <CompanyInfo company={company} />
        </div>
        
        {/* Sidebar Column */}
        <div className="col-lg-4">
          <RelatedNotices notices={relatedNotices} />
        </div>
      </div>
    </div>
  );
}


